INSERT INTO faqs (category, question, answer) VALUES
-- Ordering
('Ordering', 'Can I cancel an order after placing it?', 'Yes, you can cancel an order within 2 hours of placing it by visiting your order history page. After this window, the order may already be processed, but you can still contact support to check if cancellation is possible.'),
('Ordering', 'Can I change my delivery address after checkout?', 'If your order has not yet been dispatched, you can update your delivery address by contacting support. Once the package is shipped, address changes are no longer possible.'),
('Ordering', 'Can I order items in bulk?', 'Absolutely! We support bulk orders for parties, events, or businesses. Simply add the desired quantity to your cart, and if you need more than 50 units of an item, contact support for special arrangements.'),
('Ordering', 'Do you offer order confirmations?', 'Yes, every order generates a confirmation email within minutes. This email includes your order number, item details, and estimated delivery time.'),
('Ordering', 'Can I reorder past purchases easily?', 'Registered users can view their order history and reorder with a single click. Guests will need to manually add items again, but confirmation emails can help track past purchases.'),

-- Customer Service
('Customer Service', 'What are your support hours?', 'Our support team is available Monday through Friday from 9 AM to 6 PM CST. We also monitor urgent requests on weekends, though response times may be slower.'),
('Customer Service', 'Do you offer live chat support?', 'Yes, our chatbot is available 24/7 for FAQ-related queries. For complex issues, you can escalate to a live agent during business hours.'),
('Customer Service', 'How quickly does support respond?', 'We aim to respond to all inquiries within 24 hours. During peak seasons, responses may take up to 48 hours, but urgent issues are prioritized.'),
('Customer Service', 'Can I contact support by phone?', 'Yes, we provide a customer service hotline listed on our website. Phone support is available during business hours for urgent matters.'),
('Customer Service', 'Do you offer multilingual support?', 'Currently, we provide support in English and Spanish. We are working on expanding to more languages to serve our diverse customer base.'),

-- Payments
('Payments', 'Is my payment information secure?', 'Yes, we use industry-standard encryption and secure payment gateways to protect your information. Your card details are never stored on our servers.'),
('Payments', 'Do you offer discounts for bulk orders?', 'Yes, bulk orders may qualify for discounts depending on the quantity. Contact support for a custom quote if you’re ordering in large volumes.'),
('Payments', 'Can I use gift cards?', 'At present, we do not support gift cards. However, we are exploring partnerships to introduce this option in the near future.'),
('Payments', 'Do you charge extra fees?', 'No hidden fees are applied. The only charges are item prices, applicable taxes, and delivery fees, which are clearly shown at checkout.'),
('Payments', 'Can I split payments across methods?', 'Currently, we only support one payment method per order. We plan to add split payments in future updates.'),

-- Returns
('Returns', 'What if my item arrives damaged?', 'If your item arrives damaged, contact support within 48 hours with photos of the product. We will arrange a replacement or refund promptly.'),
('Returns', 'How do I get a refund?', 'Refunds are processed once the returned item is received and inspected. The amount will be credited back to your original payment method within 5–7 business days.'),
('Returns', 'Do you cover return shipping costs?', 'Yes, if the return is due to damage or an error on our part, we cover shipping costs. For other reasons, customers are responsible for return shipping.'),
('Returns', 'Can I exchange an item instead of returning it?', 'Yes, exchanges are possible if the item is in stock. Contact support to initiate an exchange request.'),
('Returns', 'Are there items that cannot be returned?', 'For safety and hygiene reasons, opened food items cannot be returned. Please review our return policy for full details.'),

-- Shipping
('Shipping', 'Can I schedule a delivery time?', 'Yes, registered users can select preferred delivery windows during checkout. Availability depends on your location and courier schedules.'),
('Shipping', 'Do you offer same-day delivery?', 'Same-day delivery is available in select areas for orders placed before noon. Check your zip code during checkout to see if this option is offered.'),
('Shipping', 'Can I track my delivery in real time?', 'Yes, once your order is dispatched, you’ll receive a tracking link. This allows you to monitor your package’s journey until it arrives.'),
('Shipping', 'Do you deliver to offices or workplaces?', 'Yes, we deliver to both residential and commercial addresses. Ensure someone is available to receive the package during delivery hours.'),
('Shipping', 'What happens if I miss a delivery?', 'If you miss a delivery, the courier will attempt again the next business day. Alternatively, you can reschedule or pick up the package at a local depot.'),

-- Technical Assistance
('Technical Assistance', 'How do I update my account details?', 'Log in to your account and navigate to the profile settings page. You can update your name, email, password, and delivery address there.'),
('Technical Assistance', 'Why am I not receiving confirmation emails?', 'First, check your spam or promotions folder. If emails are still missing, verify that your email address is correct in your account settings.'),
('Technical Assistance', 'Can I reset my password if I forget it?', 'Yes, click the “Forgot Password” link on the login page. You’ll receive an email with instructions to reset your password securely.'),
('Technical Assistance', 'How do I delete my account?', 'Contact support to request account deletion. Once confirmed, your account and order history will be permanently removed.'),
('Technical Assistance', 'Can I use the site on mobile devices?', 'Yes, our website is fully mobile-friendly. You can browse, order, and track deliveries seamlessly from your smartphone or tablet.');